#!/usr/bin/env node
// canli-markets-mcp: public market data for agents, from the sources themselves. SEC EDGAR
// (filings and their sections, full-text search, insider trades, 13F holdings), the US Treasury
// yield curves, FRED economic series and prices need no key; prices use the user's own Alpaca or
// Tiingo key when one is set. Every request goes from this machine straight to the source; nothing passes through Canli
// Capital, and every result names the URL it came from.
import { readFileSync, realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { McpServer } from "@modelcontextprotocol/server";
import { StdioServerTransport } from "@modelcontextprotocol/server/stdio";
import { z } from "zod";

import { createSession, evidenceScope } from "./sources.mjs";
import * as Adv from "./advisers.mjs";
import * as Cal from "./calendar.mjs";
import * as CB from "./centralbank.mjs";
import * as Earn from "./earnings.mjs";
import * as E from "./events.mjs";
import * as LF from "./latest.mjs";
import * as DF from "./diff.mjs";
import * as F from "./funds.mjs";
import * as G from "./global.mjs";
import * as O from "./ownership.mjs";
import * as Pos from "./positioning.mjs";
import * as Pay from "./pay.mjs";
import * as Opt from "./options.mjs";
import * as P from "./private.mjs";
import * as Seg from "./segments.mjs";
import * as R from "./research.mjs";
import * as T from "./tools.mjs";
import * as FS from "./statements.mjs";
import * as FT from "./filing-tables.mjs";
import * as ER from "./releases.mjs";
import * as VC from "./verify.mjs";
import * as RT from "./rates.mjs";
import * as EU from "./esef.mjs";
import * as PM from "./predictions.mjs";
import * as CR from "./crypto.mjs";

export const SERVER_NAME = "canli-markets-mcp";
export const SERVER_VERSION = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")).version;
export const SERVER_INSTRUCTIONS = "Market data and research from the public sources themselves. Before answering with a company's reported figures, check them with verify_claims: each comes back confirmed, contradicted (with the filed figure and what the wrong one matches) or not reported. Across the market: screen_companies ranks every US-listed company on fundamentals, company_report gives one company's financials, segment_revenue its revenue by segment, product and region, valuation, risk, insiders and filings in one call, event_study measures price reactions to earnings or insider trades, mentions_trend counts a phrase in filings over time. Analyst work: financial_statements gives the income statement, balance sheet and cash flows exactly as filed (several years joined, restatements and splits shown, never mixed); filing_tables finds the table that holds a figure in a filing, or follows it through several years of filings (members, stores, ARPU, guidance tables); earnings_release reads a results press release: results, guidance as ranges, and last quarter's guidance against this quarter's results. Companies: company_profile, list_filings, then read_filing (section \"risk factors\", \"md&a\" and so on for a 10-K or 10-Q; document \"EX-99.1\" for an 8-K press release); search_filings finds words across all filings; executive_pay reads a proxy's pay-versus-performance table; company_events gives a company's 8-K news (or, by event, the whole market's: restatements, bankruptcies, cyber incidents); latest_filings is what has just been filed, across every company, by form and event; filing_diff shows what changed in a 10-K's risk factors (or any item) since the last one. earnings_calendar gives a company's results dates and the next one estimated, or who reports in a window. Ownership: insider_trades (Form 4) and fund_holdings (a manager's 13F); large_holders (13D/13G: 5 percent holders and activists), investment_advisers (Form ADV); funds: fund_portfolio (what a mutual fund or ETF holds, its flows and returns, from N-PORT); private markets: private_offerings (Form D raises by startups and funds); positioning: short_interest, off_exchange_volume (FINRA dark pools), fails_to_deliver (SEC) and futures_positioning (CFTC Commitments of Traders). Rates and the economy: economic_calendar (when the data comes out), fomc (the Fed's decisions, votes and projections), treasury_yields, treasury_auctions, federal_debt, economic_series (FRED), world_economy (World Bank, every country) and economic_outlook (OECD projections). Beyond the US: european_filings (a company's ESEF annual report, the figures it tagged), reference_rates (SOFR, EFFR, €STR, ECB and Bank of England rates from the central banks, and about forty central banks' policy rates), prediction_markets (Polymarket and Kalshi prices for an outcome) and crypto_fundamentals (DefiLlama: a protocol's value locked, fees and revenue, a chain's value locked, a stablecoin's supply). Options: options_chain, volatility_surface and futures_curve (Cboe delayed data). Prices: price_history for stocks in the US and abroad, currencies, futures, indices and crypto (no key needed; the user's Alpaca or Tiingo key is used for US stocks when set). Every result has its source URL; cite it.";
export const SERVER_INFO = Object.freeze({
  name: SERVER_NAME, version: SERVER_VERSION, title: "Canli Markets",
  websiteUrl: "https://canlicapital.com/developers",
  icons: [{ src: "https://canlicapital.com/icon-512.png", mimeType: "image/png", sizes: ["512x512"] }, { src: "https://canlicapital.com/favicon.svg", mimeType: "image/svg+xml", sizes: ["any"] }],
});

